SELECT id, tenant_id, conversation_id, visitor_id, client_message_id, message_type,
       content, direction, sender_type, status, error_message, agent_user_id, source,
       create_time, update_time
FROM crm_webchat_message
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND client_message_id = #{clientMessageId}
LIMIT 1

SELECT id, tenant_id, conversation_id, visitor_id, client_message_id, message_type,
       content, direction, sender_type, status, error_message, agent_user_id, source,
       create_time, update_time
FROM crm_webchat_message
WHERE conversation_id = #{conversationId}

    AND id < #{beforeId}

ORDER BY create_time DESC, id DESC
LIMIT #{pageSize}
